/* QR Code Generator — vanilla JS, no dependencies
 * Based on qrcode-generator by Kazuhiko Arase (MIT License, https://github.com/kazuhikoarase/qrcode-generator)
 * Embedded version for offline use in DVBA apps (sello v3)
 *
 * USAGE:
 *   const qr = qrcode(0, 'M');     // typeNumber=0 → auto, errorCorrectionLevel='L'|'M'|'Q'|'H'
 *   qr.addData('https://...');
 *   qr.make();
 *   const n = qr.getModuleCount();
 *   for (let r=0; r<n; r++) for (let c=0; c<n; c++) if (qr.isDark(r,c)) { /* dot * / }
 */
var qrcode = (function () {
  'use strict';

  // ── Mode + EC Level constants ────────────────────────────────────────
  var Mode = { MODE_8BIT_BYTE: 4 };
  var ECL = { L: 1, M: 0, Q: 3, H: 2 };

  // ── QRMath — Galois field GF(256) ────────────────────────────────────
  var QRMath = (function () {
    var EXP = new Array(256), LOG = new Array(256);
    for (var i = 0; i < 8; i++) EXP[i] = 1 << i;
    for (i = 8; i < 256; i++) EXP[i] = EXP[i - 4] ^ EXP[i - 5] ^ EXP[i - 6] ^ EXP[i - 8];
    for (i = 0; i < 255; i++) LOG[EXP[i]] = i;
    return {
      glog: function (n) { if (n < 1) throw new Error('glog(' + n + ')'); return LOG[n]; },
      gexp: function (n) { while (n < 0) n += 255; while (n >= 256) n -= 255; return EXP[n]; }
    };
  })();

  // ── QRPolynomial ─────────────────────────────────────────────────────
  function QRPolynomial(num, shift) {
    var off = 0;
    while (off < num.length && num[off] === 0) off++;
    this.num = new Array(num.length - off + shift);
    for (var i = 0; i < num.length - off; i++) this.num[i] = num[i + off];
  }
  QRPolynomial.prototype.get = function (i) { return this.num[i]; };
  QRPolynomial.prototype.getLength = function () { return this.num.length; };
  QRPolynomial.prototype.multiply = function (e) {
    var num = new Array(this.getLength() + e.getLength() - 1);
    for (var i = 0; i < this.getLength(); i++)
      for (var j = 0; j < e.getLength(); j++)
        num[i + j] ^= QRMath.gexp(QRMath.glog(this.get(i)) + QRMath.glog(e.get(j)));
    return new QRPolynomial(num, 0);
  };
  QRPolynomial.prototype.mod = function (e) {
    if (this.getLength() - e.getLength() < 0) return this;
    var ratio = QRMath.glog(this.get(0)) - QRMath.glog(e.get(0));
    var num = new Array(this.getLength());
    for (var i = 0; i < this.getLength(); i++) num[i] = this.get(i);
    for (i = 0; i < e.getLength(); i++) num[i] ^= QRMath.gexp(QRMath.glog(e.get(i)) + ratio);
    return new QRPolynomial(num, 0).mod(e);
  };

  // ── RS Block tables — versions 1..10 only (enough for our URLs ~60 chars) ──
  // Each entry: [totalCount, dataCount] per block, separated by '/' for mixed counts.
  // Format per version: [L, M, Q, H] where each is [[count, totalPerBlock, dataPerBlock], ...]
  var RS_BLOCK_TABLE = [
    // v1
    [[1, 26, 19]], [[1, 26, 16]], [[1, 26, 13]], [[1, 26, 9]],
    // v2
    [[1, 44, 34]], [[1, 44, 28]], [[1, 44, 22]], [[1, 44, 16]],
    // v3
    [[1, 70, 55]], [[1, 70, 44]], [[2, 35, 17]], [[2, 35, 13]],
    // v4
    [[1, 100, 80]], [[2, 50, 32]], [[2, 50, 24]], [[4, 25, 9]],
    // v5
    [[1, 134, 108]], [[2, 67, 43]], [[2, 33, 15], [2, 34, 16]], [[2, 33, 11], [2, 34, 12]],
    // v6
    [[2, 86, 68]], [[4, 43, 27]], [[4, 43, 19]], [[4, 43, 15]],
    // v7
    [[2, 98, 78]], [[4, 49, 31]], [[2, 32, 14], [4, 33, 15]], [[4, 39, 13], [1, 40, 14]],
    // v8
    [[2, 121, 97]], [[2, 60, 38], [2, 61, 39]], [[4, 40, 18], [2, 41, 19]], [[4, 40, 14], [2, 41, 15]],
    // v9
    [[2, 146, 116]], [[3, 58, 36], [2, 59, 37]], [[4, 36, 16], [4, 37, 17]], [[4, 36, 12], [4, 37, 13]],
    // v10
    [[2, 86, 68], [2, 87, 69]], [[4, 69, 43], [1, 70, 44]], [[6, 43, 19], [2, 44, 20]], [[6, 43, 15], [2, 44, 16]]
  ];

  function getRSBlocks(typeNumber, errorCorrectionLevel) {
    // Map ECL constant (L=1, M=0, Q=3, H=2 — values used for QR format info) to table offset (L=0, M=1, Q=2, H=3)
    var offset;
    switch (errorCorrectionLevel) {
      case ECL.L: offset = 0; break;
      case ECL.M: offset = 1; break;
      case ECL.Q: offset = 2; break;
      case ECL.H: offset = 3; break;
      default: throw new Error('bad ecl: ' + errorCorrectionLevel);
    }
    var idx = (typeNumber - 1) * 4 + offset;
    if (idx < 0 || idx >= RS_BLOCK_TABLE.length) throw new Error('bad rs block @ ' + typeNumber + '/' + errorCorrectionLevel);
    var rs = RS_BLOCK_TABLE[idx];
    var blocks = [];
    for (var i = 0; i < rs.length; i++) {
      for (var j = 0; j < rs[i][0]; j++) blocks.push({ totalCount: rs[i][1], dataCount: rs[i][2] });
    }
    return blocks;
  }

  // ── QRBitBuffer ──────────────────────────────────────────────────────
  function QRBitBuffer() { this.buffer = []; this.length = 0; }
  QRBitBuffer.prototype.get = function (i) { return ((this.buffer[Math.floor(i / 8)] >>> (7 - i % 8)) & 1) === 1; };
  QRBitBuffer.prototype.put = function (num, length) {
    for (var i = 0; i < length; i++) this.putBit(((num >>> (length - i - 1)) & 1) === 1);
  };
  QRBitBuffer.prototype.putBit = function (bit) {
    var bufIdx = Math.floor(this.length / 8);
    if (this.buffer.length <= bufIdx) this.buffer.push(0);
    if (bit) this.buffer[bufIdx] |= (0x80 >>> (this.length % 8));
    this.length++;
  };

  // ── QRUtil ───────────────────────────────────────────────────────────
  var QRUtil = {
    PATTERN_POSITION_TABLE: [
      [], [6, 18], [6, 22], [6, 26], [6, 30], [6, 34],
      [6, 22, 38], [6, 24, 42], [6, 26, 46], [6, 28, 50]
    ],
    G15: (1 << 10) | (1 << 8) | (1 << 5) | (1 << 4) | (1 << 2) | (1 << 1) | (1 << 0),
    G18: (1 << 12) | (1 << 11) | (1 << 10) | (1 << 9) | (1 << 8) | (1 << 5) | (1 << 2) | (1 << 0),
    G15_MASK: (1 << 14) | (1 << 12) | (1 << 10) | (1 << 4) | (1 << 1),

    getBCHTypeInfo: function (data) {
      var d = data << 10;
      while (QRUtil.getBCHDigit(d) - QRUtil.getBCHDigit(QRUtil.G15) >= 0) {
        d ^= (QRUtil.G15 << (QRUtil.getBCHDigit(d) - QRUtil.getBCHDigit(QRUtil.G15)));
      }
      return ((data << 10) | d) ^ QRUtil.G15_MASK;
    },
    getBCHDigit: function (data) {
      var digit = 0;
      while (data !== 0) { digit++; data >>>= 1; }
      return digit;
    },
    getPatternPosition: function (typeNumber) {
      return QRUtil.PATTERN_POSITION_TABLE[typeNumber - 1];
    },
    getMask: function (maskPattern, i, j) {
      switch (maskPattern) {
        case 0: return (i + j) % 2 === 0;
        case 1: return i % 2 === 0;
        case 2: return j % 3 === 0;
        case 3: return (i + j) % 3 === 0;
        case 4: return (Math.floor(i / 2) + Math.floor(j / 3)) % 2 === 0;
        case 5: return (i * j) % 2 + (i * j) % 3 === 0;
        case 6: return ((i * j) % 2 + (i * j) % 3) % 2 === 0;
        case 7: return ((i * j) % 3 + (i + j) % 2) % 2 === 0;
      }
      throw new Error('bad maskPattern: ' + maskPattern);
    },
    getErrorCorrectPolynomial: function (errorCorrectLength) {
      var a = new QRPolynomial([1], 0);
      for (var i = 0; i < errorCorrectLength; i++) a = a.multiply(new QRPolynomial([1, QRMath.gexp(i)], 0));
      return a;
    },
    getLengthInBits: function (mode, type) {
      // mode 4 (byte) for type 1..9 = 8 bits, 10..40 = 16 bits
      if (mode !== Mode.MODE_8BIT_BYTE) throw new Error('mode: ' + mode);
      return type < 10 ? 8 : 16;
    },
    getLostPoint: function (qrCode) {
      var n = qrCode.getModuleCount(), lostPoint = 0, row, col, sameCount, dark;
      // adjacent same color: 1 row/col
      for (row = 0; row < n; row++) for (col = 0; col < n - 6; col++) {
        sameCount = 0;
        for (var r = 0; r < 7; r++) if (qrCode.isDark(row, col + r)) sameCount++;
        if (sameCount === 0 || sameCount === 7) lostPoint += 40;
      }
      // 2x2 same color
      for (row = 0; row < n - 1; row++) for (col = 0; col < n - 1; col++) {
        var c = 0;
        if (qrCode.isDark(row, col)) c++;
        if (qrCode.isDark(row + 1, col)) c++;
        if (qrCode.isDark(row, col + 1)) c++;
        if (qrCode.isDark(row + 1, col + 1)) c++;
        if (c === 0 || c === 4) lostPoint += 3;
      }
      // dark module ratio
      var darkCount = 0;
      for (col = 0; col < n; col++) for (row = 0; row < n; row++) if (qrCode.isDark(row, col)) darkCount++;
      var ratio = Math.abs(100 * darkCount / n / n - 50) / 5;
      lostPoint += ratio * 10;
      return lostPoint;
    }
  };

  // ── QR8bitByte ───────────────────────────────────────────────────────
  function QR8bitByte(data) { this.mode = Mode.MODE_8BIT_BYTE; this.data = data; this.parsedData = []; }
  QR8bitByte.prototype.getLength = function () { return this.parsedData.length; };
  QR8bitByte.prototype.write = function (buffer) {
    for (var i = 0; i < this.parsedData.length; i++) buffer.put(this.parsedData[i], 8);
  };
  QR8bitByte.prototype.parse = function () {
    // UTF-8 encode
    this.parsedData = [];
    for (var i = 0; i < this.data.length; i++) {
      var code = this.data.charCodeAt(i);
      if (code < 0x80) this.parsedData.push(code);
      else if (code < 0x800) {
        this.parsedData.push(0xC0 | (code >> 6));
        this.parsedData.push(0x80 | (code & 0x3F));
      } else {
        this.parsedData.push(0xE0 | (code >> 12));
        this.parsedData.push(0x80 | ((code >> 6) & 0x3F));
        this.parsedData.push(0x80 | (code & 0x3F));
      }
    }
  };

  // ── QRCode (main) ────────────────────────────────────────────────────
  function QRCode(typeNumber, errorCorrectionLevel) {
    this.typeNumber = typeNumber;
    this.errorCorrectionLevel = errorCorrectionLevel;
    this.modules = null;
    this.moduleCount = 0;
    this.dataList = [];
  }

  QRCode.prototype.addData = function (data) {
    var d = new QR8bitByte(data); d.parse();
    this.dataList.push(d);
  };
  QRCode.prototype.isDark = function (row, col) { return this.modules[row][col]; };
  QRCode.prototype.getModuleCount = function () { return this.moduleCount; };

  QRCode.prototype.make = function () {
    if (this.typeNumber < 1) {
      var typeNumber = 1;
      for (; typeNumber < 11; typeNumber++) {
        var rsBlocks = getRSBlocks(typeNumber, this.errorCorrectionLevel);
        var buffer = new QRBitBuffer();
        var totalDataCount = 0;
        for (var i = 0; i < rsBlocks.length; i++) totalDataCount += rsBlocks[i].dataCount;
        for (i = 0; i < this.dataList.length; i++) {
          var data = this.dataList[i];
          buffer.put(data.mode, 4);
          buffer.put(data.getLength(), QRUtil.getLengthInBits(data.mode, typeNumber));
          data.write(buffer);
        }
        if (buffer.length <= totalDataCount * 8) break;
      }
      if (typeNumber > 10) throw new Error('data too long (max version 10): ' + buffer.length);
      this.typeNumber = typeNumber;
    }
    this.makeImpl(false, this.getBestMaskPattern());
  };

  QRCode.prototype.makeImpl = function (test, maskPattern) {
    this.moduleCount = this.typeNumber * 4 + 17;
    this.modules = new Array(this.moduleCount);
    for (var row = 0; row < this.moduleCount; row++) {
      this.modules[row] = new Array(this.moduleCount);
      for (var col = 0; col < this.moduleCount; col++) this.modules[row][col] = null;
    }
    this.setupPositionProbePattern(0, 0);
    this.setupPositionProbePattern(this.moduleCount - 7, 0);
    this.setupPositionProbePattern(0, this.moduleCount - 7);
    this.setupPositionAdjustPattern();
    this.setupTimingPattern();
    this.setupTypeInfo(test, maskPattern);
    if (this.typeNumber >= 7) this.setupTypeNumber(test);
    if (this.dataCache === null || this.dataCache === undefined) {
      this.dataCache = QRCode.createData(this.typeNumber, this.errorCorrectionLevel, this.dataList);
    }
    this.mapData(this.dataCache, maskPattern);
  };

  QRCode.prototype.setupPositionProbePattern = function (row, col) {
    for (var r = -1; r <= 7; r++) {
      if (row + r <= -1 || this.moduleCount <= row + r) continue;
      for (var c = -1; c <= 7; c++) {
        if (col + c <= -1 || this.moduleCount <= col + c) continue;
        this.modules[row + r][col + c] = (0 <= r && r <= 6 && (c === 0 || c === 6))
          || (0 <= c && c <= 6 && (r === 0 || r === 6))
          || (2 <= r && r <= 4 && 2 <= c && c <= 4);
      }
    }
  };

  QRCode.prototype.getBestMaskPattern = function () {
    var minLostPoint = 0, pattern = 0;
    for (var i = 0; i < 8; i++) {
      this.makeImpl(true, i);
      var lostPoint = QRUtil.getLostPoint(this);
      if (i === 0 || minLostPoint > lostPoint) { minLostPoint = lostPoint; pattern = i; }
    }
    return pattern;
  };

  QRCode.prototype.setupTimingPattern = function () {
    for (var r = 8; r < this.moduleCount - 8; r++) {
      if (this.modules[r][6] !== null) continue;
      this.modules[r][6] = r % 2 === 0;
    }
    for (var c = 8; c < this.moduleCount - 8; c++) {
      if (this.modules[6][c] !== null) continue;
      this.modules[6][c] = c % 2 === 0;
    }
  };

  QRCode.prototype.setupPositionAdjustPattern = function () {
    var pos = QRUtil.getPatternPosition(this.typeNumber);
    for (var i = 0; i < pos.length; i++) {
      for (var j = 0; j < pos.length; j++) {
        var row = pos[i], col = pos[j];
        if (this.modules[row][col] !== null) continue;
        for (var r = -2; r <= 2; r++) for (var c = -2; c <= 2; c++) {
          this.modules[row + r][col + c] = (r === -2 || r === 2 || c === -2 || c === 2 || (r === 0 && c === 0));
        }
      }
    }
  };

  QRCode.prototype.setupTypeNumber = function (test) {
    var bits = this.typeNumber << 12;
    var d = bits;
    while (QRUtil.getBCHDigit(d) - QRUtil.getBCHDigit(QRUtil.G18) >= 0) {
      d ^= (QRUtil.G18 << (QRUtil.getBCHDigit(d) - QRUtil.getBCHDigit(QRUtil.G18)));
    }
    bits = (this.typeNumber << 12) | d;
    for (var i = 0; i < 18; i++) {
      var mod = !test && ((bits >> i) & 1) === 1;
      this.modules[Math.floor(i / 3)][i % 3 + this.moduleCount - 8 - 3] = mod;
      this.modules[i % 3 + this.moduleCount - 8 - 3][Math.floor(i / 3)] = mod;
    }
  };

  QRCode.prototype.setupTypeInfo = function (test, maskPattern) {
    var data = (this.errorCorrectionLevel << 3) | maskPattern;
    var bits = QRUtil.getBCHTypeInfo(data);
    for (var i = 0; i < 15; i++) {
      var mod = !test && ((bits >> i) & 1) === 1;
      if (i < 6) this.modules[i][8] = mod;
      else if (i < 8) this.modules[i + 1][8] = mod;
      else this.modules[this.moduleCount - 15 + i][8] = mod;
    }
    for (i = 0; i < 15; i++) {
      mod = !test && ((bits >> i) & 1) === 1;
      if (i < 8) this.modules[8][this.moduleCount - i - 1] = mod;
      else if (i < 9) this.modules[8][15 - i - 1 + 1] = mod;
      else this.modules[8][15 - i - 1] = mod;
    }
    this.modules[this.moduleCount - 8][8] = !test;
  };

  QRCode.prototype.mapData = function (data, maskPattern) {
    var inc = -1, row = this.moduleCount - 1, bitIndex = 7, byteIndex = 0;
    for (var col = this.moduleCount - 1; col > 0; col -= 2) {
      if (col === 6) col--;
      while (true) {
        for (var c = 0; c < 2; c++) {
          if (this.modules[row][col - c] === null) {
            var dark = false;
            if (byteIndex < data.length) dark = ((data[byteIndex] >>> bitIndex) & 1) === 1;
            var mask = QRUtil.getMask(maskPattern, row, col - c);
            if (mask) dark = !dark;
            this.modules[row][col - c] = dark;
            bitIndex--;
            if (bitIndex === -1) { byteIndex++; bitIndex = 7; }
          }
        }
        row += inc;
        if (row < 0 || this.moduleCount <= row) { row -= inc; inc = -inc; break; }
      }
    }
  };

  QRCode.PAD0 = 0xEC;
  QRCode.PAD1 = 0x11;

  QRCode.createData = function (typeNumber, errorCorrectionLevel, dataList) {
    var rsBlocks = getRSBlocks(typeNumber, errorCorrectionLevel);
    var buffer = new QRBitBuffer();
    for (var i = 0; i < dataList.length; i++) {
      var data = dataList[i];
      buffer.put(data.mode, 4);
      buffer.put(data.getLength(), QRUtil.getLengthInBits(data.mode, typeNumber));
      data.write(buffer);
    }
    var totalDataCount = 0;
    for (i = 0; i < rsBlocks.length; i++) totalDataCount += rsBlocks[i].dataCount;
    if (buffer.length > totalDataCount * 8) throw new Error('code length overflow');
    if (buffer.length + 4 <= totalDataCount * 8) buffer.put(0, 4);
    while (buffer.length % 8 !== 0) buffer.putBit(false);
    while (true) {
      if (buffer.length >= totalDataCount * 8) break;
      buffer.put(QRCode.PAD0, 8);
      if (buffer.length >= totalDataCount * 8) break;
      buffer.put(QRCode.PAD1, 8);
    }
    return QRCode.createBytes(buffer, rsBlocks);
  };

  QRCode.createBytes = function (buffer, rsBlocks) {
    var offset = 0, maxDcCount = 0, maxEcCount = 0;
    var dcdata = new Array(rsBlocks.length), ecdata = new Array(rsBlocks.length);
    for (var r = 0; r < rsBlocks.length; r++) {
      var dcCount = rsBlocks[r].dataCount;
      var ecCount = rsBlocks[r].totalCount - dcCount;
      maxDcCount = Math.max(maxDcCount, dcCount);
      maxEcCount = Math.max(maxEcCount, ecCount);
      dcdata[r] = new Array(dcCount);
      for (var i = 0; i < dcdata[r].length; i++) dcdata[r][i] = 0xff & buffer.buffer[i + offset];
      offset += dcCount;
      var rsPoly = QRUtil.getErrorCorrectPolynomial(ecCount);
      var rawPoly = new QRPolynomial(dcdata[r], rsPoly.getLength() - 1);
      var modPoly = rawPoly.mod(rsPoly);
      ecdata[r] = new Array(rsPoly.getLength() - 1);
      for (i = 0; i < ecdata[r].length; i++) {
        var idx = i + modPoly.getLength() - ecdata[r].length;
        ecdata[r][i] = idx >= 0 ? modPoly.get(idx) : 0;
      }
    }
    var totalCodeCount = 0;
    for (i = 0; i < rsBlocks.length; i++) totalCodeCount += rsBlocks[i].totalCount;
    var data = new Array(totalCodeCount);
    var index = 0;
    for (i = 0; i < maxDcCount; i++) for (r = 0; r < rsBlocks.length; r++)
      if (i < dcdata[r].length) data[index++] = dcdata[r][i];
    for (i = 0; i < maxEcCount; i++) for (r = 0; r < rsBlocks.length; r++)
      if (i < ecdata[r].length) data[index++] = ecdata[r][i];
    return data;
  };

  // Factory
  return function (typeNumber, errorCorrectionLevel) {
    var ecl = (typeof errorCorrectionLevel === 'string') ? ECL[errorCorrectionLevel] : errorCorrectionLevel;
    if (ecl === undefined) ecl = ECL.M;
    return new QRCode(typeNumber, ecl);
  };
})();
